/**
 * The shift handover: what happened on my shift, what is still open, what the
 * next person has to watch.
 *
 * The data sections are generated by the engine from real records
 * (`handover.generate`) and **every item links to the record it came from**.
 * That is the point of this tab rather than a nicety: a summary nobody can
 * check is worse than no summary, because it will be trusted anyway. So the
 * screen renders what `handoverSections` produced and nothing else — it adds
 * no figure, rounds nothing, and merges nothing.
 *
 * Three states are kept apart everywhere:
 *
 * - a section with items;
 * - a section that was read and had nothing in it ("No backup failed.");
 * - a section that could not be read at all, with the engine's reason.
 *
 * The prose box is the only part a person writes, and `handover.save`
 * regenerates every data section on the server, so nothing typed here — or
 * written by a model asked to tidy it — can become a number in a saved
 * handover.
 */

import { ClipboardList, FileDown, Save, Sparkles, Trash2, Wand2 } from 'lucide-react';
import { useEffect, useState } from 'react';
import { Link } from 'react-router';
import { useHasMethod } from '@/api/hooks';
import type { HandoverHead } from '@/api/types/ops';
import { Badge } from '@/design/Badge';
import { Button } from '@/design/Button';
import { confirm } from '@/design/Dialog';
import { EmptyState } from '@/design/EmptyState';
import { ErrorState } from '@/design/ErrorState';
import { Field } from '@/design/Field';
import { Input } from '@/design/Input';
import { Panel } from '@/design/Panel';
import { Select } from '@/design/Select';
import { Skeleton } from '@/design/Skeleton';
import { LabPill, StatusPill } from '@/design/StatusPill';
import { Textarea } from '@/design/Textarea';
import { TimeAgo } from '@/design/TimeAgo';
import { toast } from '@/design/Toast';
import { Toolbar, ToolbarSpacer } from '@/design/Toolbar';
import { formatCount, plural } from '@/lib/format';
import { formatDateTime, formatTimestamp } from '@/lib/time';
import { useAuthor } from './author';
import {
  useDeleteHandover,
  useHandover,
  useSaveHandover,
  useSavedHandover,
  useSavedHandovers,
  useTidyNotes,
} from './data';
import { ExportDialog } from './ExportDialog';
import styles from './Handover.module.css';
import opsStyles from './Ops.module.css';
import { PERIODS, handoverSections, instant, periodChoice, type HandoverItem } from './ops';
import { NothingHappened, UnavailableNote } from './Unavailable';

/** `<input type="datetime-local">` wants local wall-clock text. */
function toLocalInput(at: number): string {
  const date = new Date(at - new Date(at).getTimezoneOffset() * 60_000);
  return date.toISOString().slice(0, 16);
}

export function HandoverTab() {
  const [periodId, setPeriodId] = useState('8h');
  // The period is pinned the moment the tab opens, so the figures do not move
  // under the person reading them. "Now" is a choice, made by pressing it.
  const [since, setSince] = useState(() => periodChoice('8h').since(Date.now()));
  const [until, setUntil] = useState(() => Date.now());
  const [notes, setNotes] = useState('');
  const [savedId, setSavedId] = useState<string | null>(null);
  const [exporting, setExporting] = useState(false);
  const [author, setAuthor] = useAuthor();

  const handover = useHandover(since, until);
  const save = useSaveHandover();
  const tidy = useTidyNotes();
  // "Ask the assistant" only exists where there is an assistant to ask.
  const hasAssistant = useHasMethod('ai.send');

  const choose = (id: string) => {
    setPeriodId(id);
    const now = Date.now();
    setSince(periodChoice(id).since(now));
    setUntil(now);
    setSavedId(null);
  };

  if (handover.isError) {
    return (
      <ErrorState
        title="The handover could not be generated"
        error={handover.error}
        onRetry={() => void handover.refetch()}
      />
    );
  }

  const sections = handover.data ? handoverSections(handover.data) : [];
  const unreadable = handover.data?.unavailable ?? [];

  return (
    <>
      <Toolbar>
        <Select
          aria-label="Period"
          size="sm"
          className={opsStyles.narrow}
          value={periodId}
          options={[
            ...PERIODS.map((period) => ({
              value: period.id,
              label: period.label,
            })),
            { value: 'custom', label: 'Exactly…' },
          ]}
          onChange={(event) => {
            if (event.target.value === 'custom') setPeriodId('custom');
            else choose(event.target.value);
          }}
        />
        {periodId === 'custom' && (
          <>
            <Input
              size="sm"
              type="datetime-local"
              aria-label="Shift start"
              className={opsStyles.when}
              value={toLocalInput(since)}
              onChange={(event) => {
                const at = new Date(event.target.value).getTime();
                if (Number.isFinite(at)) setSince(at);
              }}
            />
            <Input
              size="sm"
              type="datetime-local"
              aria-label="Shift end"
              className={opsStyles.when}
              value={toLocalInput(until)}
              onChange={(event) => {
                const at = new Date(event.target.value).getTime();
                if (Number.isFinite(at)) setUntil(at);
              }}
            />
          </>
        )}
        <Button
          size="sm"
          variant="ghost"
          onClick={() => choose(periodId === 'custom' ? '8h' : periodId)}
        >
          Bring it up to now
        </Button>
        <ToolbarSpacer />
        <Button
          variant="secondary"
          icon={FileDown}
          disabled={!handover.data}
          onClick={() => setExporting(true)}
        >
          Export
        </Button>
        <Button
          variant="primary"
          icon={Save}
          loading={save.isPending}
          disabled={!handover.data}
          onClick={() =>
            save.mutate(
              { since, until, notes, id: savedId ?? undefined },
              { onSuccess: (stored) => setSavedId(stored.id) },
            )
          }
        >
          {savedId === null ? 'Save handover' : 'Save again'}
        </Button>
      </Toolbar>

      <p className={opsStyles.facts}>
        <span title={formatTimestamp(since)}>
          From <b>{formatDateTime(since)}</b>
        </span>
        <span title={formatTimestamp(until)}>
          to <b>{formatDateTime(until)}</b>
        </span>
        <span className={opsStyles.muted}>
          {periodId === 'custom' ? 'Exactly as set.' : periodChoice(periodId).hint} The period is
          half-open, so two consecutive handovers neither overlap nor leave a minute out.
        </span>
        {handover.data && (
          <span className={opsStyles.muted}>
            read <TimeAgo at={instant(handover.data.generated_at)} />
          </span>
        )}
      </p>

      {unreadable.length > 0 && (
        <div className={styles.warnings}>
          <p className={styles.warningHead}>
            {plural(unreadable.length, 'section')} of this handover could not be read. What is
            missing from them is not necessarily nothing.
          </p>
        </div>
      )}

      <div className={opsStyles.columns}>
        <div className={styles.sections}>
          {handover.isPending && (
            <div aria-busy="true" className={styles.sections}>
              <Skeleton shape="block" height={120} />
              <Skeleton shape="block" height={120} />
              <Skeleton shape="block" height={120} />
            </div>
          )}
          {sections.map((section) => (
            <div key={section.id} data-section={section.id} className={styles.sectionWrap}>
              <Panel
                title={section.title}
                storageId={`ops.handover.${section.id}`}
                collapsible
                actions={
                  section.body.kind === 'items' ? (
                    <Badge tone="neutral" variant="outline">
                      {formatCount(section.body.items.length)}
                    </Badge>
                  ) : undefined
                }
              >
                <div className={styles.section}>
                  {section.summary && <p className={styles.summary}>{section.summary}</p>}
                  {section.note && <p className={styles.note}>{section.note}</p>}
                  {section.body.kind === 'items' && (
                    <ul className={styles.items}>
                      {section.body.items.map((item) => (
                        <Item key={item.id} item={item} />
                      ))}
                    </ul>
                  )}
                  {section.body.kind === 'nothing' && (
                    <NothingHappened size="inline" sentence={section.body.sentence} />
                  )}
                  {section.body.kind === 'unavailable' && (
                    <UnavailableNote
                      size="block"
                      reason={section.body.reason}
                      message={section.body.message}
                    />
                  )}
                </div>
              </Panel>
            </div>
          ))}
        </div>

        <aside className={styles.aside}>
          <Panel
            title="Notes for the next shift"
            actions={
              hasAssistant === true ? (
                <Button
                  size="sm"
                  variant="ai"
                  icon={Wand2}
                  loading={tidy.running}
                  disabled={notes.trim() === ''}
                  onClick={() => tidy.ask({ notes, period: { since, until } })}
                >
                  Tidy my notes
                </Button>
              ) : undefined
            }
          >
            <div className={styles.notesBody}>
              <Textarea
                aria-label="Notes for the next shift"
                rows={8}
                value={notes}
                placeholder="What the next shift needs to know that the sections beside this do not say."
                onChange={(event) => setNotes(event.target.value)}
              />
              <p className={styles.notesHint}>
                The only part of a handover a person writes. Saving regenerates every section above
                from the records, so nothing written here can become a figure.
              </p>
              <Field label="Your name" hint="Stored with the handover. Remembered in this browser.">
                <Input
                  size="sm"
                  value={author}
                  placeholder="who is writing this"
                  onChange={(event) => setAuthor(event.target.value)}
                />
              </Field>
              {savedId !== null && (
                <p className={styles.saved}>
                  Saved.{' '}
                  <Link to={`/ops/handover?saved=${encodeURIComponent(savedId)}`}>This one</Link> is
                  in the list below; saving again replaces it.
                </p>
              )}
            </div>
          </Panel>

          {(tidy.text !== '' || tidy.running || tidy.error !== null) && (
            <Tidied
              text={tidy.text}
              running={tidy.running}
              error={tidy.error}
              onUse={() => {
                setNotes(tidy.text.trim());
                tidy.discard();
                toast.success('The tidied wording replaced your notes');
              }}
              onDiscard={tidy.discard}
            />
          )}

          <SavedList openSaved={savedId} onOpen={(id) => setSavedId(id)} onNotes={setNotes} />
        </aside>
      </div>

      <ExportDialog
        open={exporting}
        onClose={() => setExporting(false)}
        method="handover.export"
        params={savedId !== null ? { id: savedId } : { since, until, notes }}
        title="Export this handover"
        description="Generated by the engine from the period, with your notes as written."
      />
    </>
  );
}

function Item({ item }: { item: HandoverItem }) {
  return (
    <li className={styles.item} data-testid="handover-item" data-tone={item.tone ?? 'idle'}>
      <Link
        to={item.to}
        className={styles.itemLink}
        title={`Open the record this came from: ${item.to}`}
      >
        {item.text}
      </Link>
      {item.lab && <LabPill />}
      {item.at != null && (
        <span className={styles.itemWhen}>
          <TimeAgo at={item.at} />
        </span>
      )}
      {item.detail && <span className={styles.itemDetail}>{item.detail}</span>}
    </li>
  );
}

/** The assistant's proposal: tinted `--ai`, and not used until a person says so. */
function Tidied({
  text,
  running,
  error,
  onUse,
  onDiscard,
}: {
  text: string;
  running: boolean;
  error: unknown;
  onUse: () => void;
  onDiscard: () => void;
}) {
  const message = error instanceof Error ? error.message : typeof error === 'string' ? error : null;
  return (
    <Panel
      title="The assistant’s wording"
      actions={
        <>
          <Button size="sm" variant="ghost" onClick={onDiscard}>
            Discard
          </Button>
          <Button
            size="sm"
            variant="ai"
            icon={Sparkles}
            disabled={running || text.trim() === ''}
            onClick={onUse}
          >
            Use this
          </Button>
        </>
      }
    >
      <div className={styles.proposal}>
        {message !== null ? (
          <p className={styles.proposalError}>{message}</p>
        ) : (
          <>
            <p className={styles.proposalNote}>
              A proposal, not a saving. It was given your prose only — never the sections above —
              and the engine regenerates every figure when the handover is saved.
            </p>
            <pre className={styles.proposalText}>{text || (running ? 'Thinking…' : '')}</pre>
          </>
        )}
      </div>
    </Panel>
  );
}

function SavedList({
  openSaved,
  onOpen,
  onNotes,
}: {
  openSaved: string | null;
  onOpen: (id: string) => void;
  onNotes: (notes: string) => void;
}) {
  const saved = useSavedHandovers();
  const remove = useDeleteHandover();
  const opened = useSavedHandover(openSaved);

  // Opening a saved handover brings its prose back into the box: it is the
  // only part that was stored as written.
  useEffect(() => {
    if (opened.data) onNotes(opened.data.notes);
  }, [opened.data]);

  return (
    <Panel title="Saved handovers" padding={saved.data?.handovers.length ? 'none' : 'md'}>
      {saved.isPending && <Skeleton shape="block" height={80} />}
      {saved.isError && <p className={styles.proposalError}>{saved.error.message}</p>}
      {saved.data && saved.data.handovers.length === 0 && (
        <EmptyState
          size="compact"
          icon={ClipboardList}
          title="None saved yet"
          description="A saved handover keeps the period and your notes; its figures are made again from the records every time it is read."
        />
      )}
      {saved.data && saved.data.handovers.length > 0 && (
        <ul className={styles.savedList}>
          {saved.data.handovers.map((head) => (
            <SavedRow
              key={head.id}
              head={head}
              current={head.id === openSaved}
              onOpen={() => onOpen(head.id)}
              onDelete={async () => {
                const sure = await confirm({
                  title: 'Delete this saved handover?',
                  description:
                    'The records it was made from are untouched; only the saved copy and its notes go.',
                  confirmLabel: 'Delete it',
                  tone: 'danger',
                });
                if (sure) remove.mutate({ id: head.id });
              }}
            />
          ))}
        </ul>
      )}
    </Panel>
  );
}

function SavedRow({
  head,
  current,
  onOpen,
  onDelete,
}: {
  head: HandoverHead;
  current: boolean;
  onOpen: () => void;
  onDelete: () => void;
}) {
  // A count the engine could not make is `null`, and null is not nought.
  const count = (value: number | null | undefined, word: string) =>
    value == null ? (
      <span className={styles.unknown} title="That section had no source when this was saved.">
        {word}: not known
      </span>
    ) : (
      <span>
        {formatCount(value)} {word}
      </span>
    );

  return (
    <li className={styles.savedRow} data-current={current || undefined}>
      <button type="button" className={styles.savedOpen} onClick={onOpen}>
        <span className={styles.savedWhen}>
          {formatDateTime(head.period.since)} → {formatDateTime(head.period.until)}
        </span>
        <span className={styles.savedCounts}>
          {count(head.incidents_opened, 'incidents')}
          {count(head.alerts_fired, 'alerts')}
          {count(head.changes_applied, 'changes applied')}
          {head.has_notes ? (
            <span>with notes</span>
          ) : (
            <span className={styles.unknown}>no notes</span>
          )}
          {head.unavailable.length > 0 && (
            <StatusPill
              tone="warn"
              title={head.unavailable.map((entry) => entry.message).join('\n')}
            >
              {plural(head.unavailable.length, 'gap')}
            </StatusPill>
          )}
        </span>
        {head.author && <span className={styles.savedAuthor}>{head.author}</span>}
      </button>
      <Button
        size="sm"
        variant="ghost"
        icon={Trash2}
        aria-label="Delete this saved handover"
        onClick={onDelete}
      />
    </li>
  );
}
